    good_assigns = []
    for bits in itertools.product([0,1], repeat=len(all_vars)):
        assign = dict(zip(all_vars, bits))
        if all(satisfies(assign, c) for c in clauses):
            good_assigns.append(assign)
    if not good_assigns:
        return False
    # check condition
    for a in good_assigns:
        if a['x'] + a['nx'] != 1:
            return False
    # ensure both possibilities exist
    vals = {(a['x'], a['nx']) for a in good_assigns}
    return vals == {(1,0),(0,1)}

