vars_base = ['x','nx']
extra = ['p','q','r']
all_vars = vars_base + extra

# generate all possible 3-element subsets of distinct vars for clauses
clause_candidates = list(itertools.combinations(all_vars, 3))

# evaluate gadget: list of clauses (each tuple of var names)

def satisfies(assign, clause):
    # assign dict var->0/1
    s = sum(assign[v] for v in clause)
    return s == 1

def is_gadget_ok(clauses):
    # check that any satisfying assignment must have x xor nx =1
    # and there exists at least one satisfying assignment for each xor outcome? Actually we need both possibilities allowed.
    # We'll check that all assignments satisfying all clauses have x xor nx =1, and both possibilities appear.
    good_assigns = []
    for bits in itertools.product([0,1], repeat=len(all_vars)):
        assign = dict(zip(all_vars, bits))
        if all(satisfies(assign, c) for c in clauses):
            good_assigns.append(assign)
    if not good_assigns:
        return False
    # check condition
    for a in good_assigns:
        if a['x'] + a['nx'] != 1:
            return False
    # ensure both possibilities exist
    vals = {(a['x'], a['nx']) for a in good_assigns}
    return vals == {(1,0),(0,1)}

for r in range(1,5):
    for combo in itertools.combinations(clause_candidates, r):
        if is_gadget_ok(combo):
            print('found', r, combo)
            raise SystemExit
